"""Build the public, offline-capable atlas UI from the existing metadata payload.

Run after visualize.py. This renderer never reads lyrics, embeddings, or private
results, and neither recomputes nor changes any analytical result.
"""
from argparse import ArgumentParser
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
SITE = HERE.parents[1] / "static" / "research" / "fear-lyrics"


def build(data_path=SITE / "atlas-data.json", output_path=SITE / "atlas.html"):
    payload = json.loads(Path(data_path).read_text(encoding="utf-8"))
    if not isinstance(payload.get("models"), list) or not payload["models"]:
        raise ValueError("atlas-data.json must contain at least one model")
    if not isinstance(payload.get("songs"), list):
        raise ValueError("atlas-data.json must contain public song metadata")
    output_path = Path(output_path)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(HTML, encoding="utf-8")
    print(json.dumps({"atlas": str(output_path), "models": len(payload["models"]),
                      "songs": len(payload["songs"]), "renderer": "atlas_v2",
                      "data": str(data_path)}, ensure_ascii=False))


